function resolvedPromptAnswer(e,t=[]){if(e.outcome!==`accepted`&&e.outcome!==`declined`)return`No longer needed`;if(e.kind===`approval`)return e.outcome===`accepted`?`Approved`:`Cancelled`;let{answer:n}=e;return t.find(e=>e.id===n?.optionId)?.label??n?.text}function resolvedPromptLabel(e,t=[]){let n=resolvedPromptAnswer(e,t);return isAnswered(e)?n===void 0?`Answered`:`Answered: ${n}`:n??``}function isAnswered(e){return e.kind!==`approval`&&(e.outcome===`accepted`||e.outcome===`declined`)}export{isAnswered,resolvedPromptAnswer,resolvedPromptLabel};